from solution import multiply
import pytest
from hypothesis import given
import hypothesis.strategies as st


def expected_unit_product(a, b):
    """Obviously-correct reference: product of absolute unit digits."""
    return abs(a) % 10 * (abs(b) % 10)


# --- Explicit spec examples ---

def test_example_148_412():
    assert multiply(148, 412) == 16


def test_example_19_28():
    assert multiply(19, 28) == 72


def test_example_2020_1851():
    assert multiply(2020, 1851) == 0


def test_example_14_neg15():
    assert multiply(14, -15) == 20


# --- Negative unit-digit handling (spec implies |-15| -> 5) ---

def test_negative_first_operand_unit():
    # unit of -19 is 9, 9*8=72; naive a%10 in Python gives 1*8=8
    assert multiply(-19, 28) == 72


def test_negative_second_operand_unit():
    assert multiply(19, -28) == 72


def test_both_negative_units():
    assert multiply(-19, -28) == 72


def test_negative_ending_1():
    # unit of -11 is 1, 1*1=1; Python -11%10==9 would give 81
    assert multiply(-11, 11) == 1
    assert multiply(11, -11) == 1
    assert multiply(-11, -11) == 1


def test_negative_trailing_zero():
    assert multiply(-20, 15) == 0
    assert multiply(20, -15) == 0


# --- Property-based tests against reference model ---

@given(st.integers(min_value=-100000, max_value=100000),
       st.integers(min_value=-100000, max_value=100000))
def test_reference_model_equivalence(a, b):
    assert multiply(a, b) == expected_unit_product(a, b)


@given(st.integers(min_value=-100000, max_value=100000),
       st.integers(min_value=-100000, max_value=100000))
def test_property_commutative(a, b):
    assert multiply(a, b) == multiply(b, a)


@given(st.integers(min_value=-100000, max_value=100000),
       st.integers(min_value=-100000, max_value=100000))
def test_property_nonnegative_bounded(a, b):
    r = multiply(a, b)
    assert 0 <= r <= 81


@given(st.integers(min_value=-100000, max_value=100000),
       st.integers(min_value=-100000, max_value=100000))
def test_property_sign_invariance(a, b):
    # unit digit ignores sign per spec example multiply(14,-15)==20
    assert multiply(a, b) == multiply(abs(a), abs(b))
    assert multiply(-a, b) == multiply(a, b)
    assert multiply(a, -b) == multiply(a, b)
    assert multiply(-a, -b) == multiply(a, b)


@given(st.integers(min_value=-10000, max_value=10000),
       st.integers(min_value=-10000, max_value=10000))
def test_property_last_digit_only_matters(a, b):
    # adding multiples of 10 must not change result
    assert multiply(a + 10, b) == multiply(a, b)
    assert multiply(a, b + 10) == multiply(a, b)
    assert multiply(a + 100, b - 100) == multiply(a, b)


@given(st.integers(min_value=0, max_value=10000))
def test_property_zero_unit_gives_zero(a):
    assert multiply(a * 10, 7) == 0
    assert multiply(7, a * 10) == 0
    assert multiply(a * 10, a * 10) == 0


@given(st.integers(min_value=0, max_value=9), st.integers(min_value=0, max_value=9))
def test_property_single_digits_are_plain_product(x, y):
    assert multiply(x, y) == x * y


@given(st.integers(min_value=-100000, max_value=100000))
def test_property_identity_with_one(a):
    # x*1 digit product == unit digit of a
    assert multiply(a, 1) == abs(a) % 10
    assert multiply(1, a) == abs(a) % 10
    assert multiply(a, 11) == abs(a) % 10
